pub fn answer() -> usize { 7 }

// The same held source is the support library and its explicit Cargo build script.
fn main() {
    let out = std::path::PathBuf::from(std::env::var_os("OUT_DIR").expect("Cargo OUT_DIR"));
    let source = out.join("header-smoke.c");
    let object = out.join("header-smoke.o");
    std::fs::write(&source, b"#include <stdio.h>\nint header_smoke(void) { return EOF; }\n")
        .expect("write private C header probe");
    let status = std::process::Command::new("cc")
        .args(["-c", "-O0"]).arg(&source).arg("-o").arg(&object)
        .status().expect("launch explicitly granted cc alias");
    assert!(status.success(), "C-header compiler probe failed: {status}");
    let metadata = std::fs::symlink_metadata(&object).expect("C-header object missing");
    assert!(metadata.is_file() && metadata.len() > 0, "C-header object empty or not regular");
    println!("cargo:rerun-if-changed=src/lib.rs");
    println!("cargo:warning=forge-header-smoke object_bytes={}", metadata.len());
}
